"""Testsuite der Referenz-Demo (Lastenheft N-11): gleichzeitig Abnahmeliste für die echte Website.

Aufruf:  python build.py && python test_app.py      (Ergebnis: test_results.json, Bilder: shots/)
Aufbau:  1. Seitenrundgang in 4 Breiten (360/390/430/1280): Überlauf, Überschriften, Barrierefreiheit, Fotos
         2. Recht und Ansprache (nur 390): externe Anfragen, Spenden, Du-Form, N-13
         3. Abläufe (nur 390): Formulare, Login und Rollen, Freigabe, Fotos, Bearbeiten/Ausblenden/Löschen,
            Demo-Steuerung, Jubiläum und Datum, Tastatur
Exit-Code 1, sobald eine Prüfung fehlschlägt.
"""
import asyncio, json, os, sys
from playwright.async_api import async_playwright

from pathlib import Path
HERE = Path(__file__).resolve().parent
SHOTS = HERE / 'shots'; SHOTS.mkdir(exist_ok=True)
URL = (HERE / 'index.html').as_uri()
ROUTES = ['start','jubilaeum','aktuelles','einsaetze','termine','buerger','foerdern','mitmachen','fahrzeuge','jugend','verein','partner','impressum','datenschutz','login']
VIEWS = [('360', dict(width=360, height=780), True), ('390', dict(width=390, height=844), True), ('430', dict(width=430, height=932), True), ('1280', dict(width=1280, height=900), False)]
results = []
def rec(ok, name, detail=''):
    results.append((ok, name, detail))
    print(('PASS ' if ok else 'FAIL ') + name + (' – ' + detail if detail else ''))

A11Y_JS = r'''() => {
  const out = [];
  const vis = el => { const r = el.getBoundingClientRect(); const cs = getComputedStyle(el); return r.width > 0 && r.height > 0 && cs.visibility !== 'hidden' && !el.closest('[inert]'); };
  const name = el => (el.getAttribute('aria-label') || el.textContent || el.getAttribute('title') || '').trim();
  document.querySelectorAll('button, a[href]').forEach(el => { if (vis(el) && !name(el)) out.push('no-name:' + el.outerHTML.slice(0, 80)); });
  document.querySelectorAll('input, select, textarea').forEach(el => { if (!el.closest('label') && !el.getAttribute('aria-label')) out.push('no-label:' + el.outerHTML.slice(0, 80)); });
  document.querySelectorAll('[role=img]').forEach(el => { if (!el.getAttribute('aria-label')) out.push('img-no-label'); });
  const ids = {}; document.querySelectorAll('[id]').forEach(el => { ids[el.id] = (ids[el.id] || 0) + 1; });
  Object.entries(ids).forEach(([k, v]) => { if (v > 1) out.push('dup-id:' + k); });
  const small = [];
  document.querySelectorAll('main button, main .btn, .top button, .top .n112p, .btabs a, .fab, .chip').forEach(el => { if (!vis(el)) return; const r = el.getBoundingClientRect(); if (r.height < 43.5 || r.width < 43.5) small.push(name(el).slice(0, 30) + ' ' + Math.round(r.width) + 'x' + Math.round(r.height)); });
  if (small.length) out.push('small-targets:' + small.join(' | '));
  if (!document.querySelector('h1')) out.push('no-h1');
  document.querySelectorAll('img').forEach(im => { if (!im.hasAttribute('alt')) out.push('img-no-alt'); if (!im.complete || im.naturalWidth === 0) out.push('img-broken:' + (im.alt||'').slice(0,30)); });
  return out;
}'''

async def main():
    async with async_playwright() as p:
        # Browser: Umgebungsvariable CHROME (Pfad), sonst das von Playwright installierte Chromium
        exe = os.environ.get('CHROME') or ('/usr/bin/google-chrome' if os.path.exists('/usr/bin/google-chrome') else None)
        br = await p.chromium.launch(executable_path=exe, args=['--no-sandbox']) if exe else await p.chromium.launch()
        for vname, vp, mobile in VIEWS:
            ctx = await br.new_context(viewport=vp, is_mobile=mobile, has_touch=mobile, device_scale_factor=2 if mobile else 1, locale='de-DE')
            pg = await ctx.new_page()
            errs = []
            pg.on('pageerror', lambda e: errs.append('pageerror: ' + str(e)))
            pg.on('console', lambda m: errs.append('console: ' + m.text) if m.type == 'error' and 'fonts.g' not in m.text and 'ERR_' not in m.text else None)
            await pg.goto(URL); await pg.wait_for_timeout(400)
            # Routen
            for r in ROUTES:
                await pg.evaluate(f"location.hash = '{r}'"); await pg.wait_for_timeout(120)
                sw = await pg.evaluate('document.documentElement.scrollWidth')
                h1 = await pg.evaluate("(document.querySelector('h1')||{}).textContent||''")
                a11y = await pg.evaluate(A11Y_JS)
                rec(sw <= vp['width'], f'[{vname}] #{r} kein horizontaler Überlauf', f'scrollWidth={sw}')
                rec(bool(h1.strip()), f'[{vname}] #{r} hat Überschrift', h1.strip()[:40])
                hard = [x for x in a11y if not x.startswith('small-targets')]
                rec(not hard, f'[{vname}] #{r} Barrierefreiheit-Basics', '; '.join(hard)[:300])
                soft = [x for x in a11y if x.startswith('small-targets')]
                if soft: rec(False, f'[{vname}] #{r} Tippziele ≥44px', soft[0][:300])
                if vname in ('390', '1280'):
                    await pg.screenshot(path=str(SHOTS / f'app-{vname}-{r}.png'), full_page=True)
            await pg.evaluate("location.hash='fahrzeuge'"); await pg.wait_for_timeout(200)
            n = await pg.evaluate("[...document.querySelectorAll('main img')].filter(i => i.complete && i.naturalWidth > 0).length")
            rec(n == 14, f'[{vname}] Fahrzeugseite zeigt alle Fotos inkl. Wechsellader', str(n))
            rec('Wechselladerfahrzeug' in await pg.inner_text('main'), f'[{vname}] Wechsellader vorgestellt')
            rec('Kunert' not in await pg.inner_text('body'), f'[{vname}] Urheberschaft einheitlich Feuerwehr Piflas')
            await pg.evaluate("location.hash='start'"); await pg.wait_for_timeout(200)
            n = await pg.evaluate("[...document.querySelectorAll('main img')].filter(i => i.complete && i.naturalWidth > 0).length")
            rec(n >= 11, f'[{vname}] Startseite zeigt Fotos (Bühne, Vereinsleben, 9 Instagram-Kacheln)', str(n))
            rec(await pg.locator('.ig img').count() == 9, f'[{vname}] Instagram-Raster voll (9 Kacheln)')
            hs = await pg.evaluate("[...document.querySelectorAll('.ig img')].map(i => Math.round(i.getBoundingClientRect().height))")
            rec(min(hs) > 60, f'[{vname}] Instagram-Bilder haben echte Höhe', str(hs[:3]))
            mt = await pg.inner_text('main')
            rec('Werde Fördermitglied' not in mt, f'[{vname}] Kein doppelter Fördermitglied-Block')
            rec('Unsere Fahrzeuge' not in mt and 'Wechsellader' not in mt, f'[{vname}] Keine Fahrzeug-Infos auf der Startseite')
            rec('Aus dem Vereinsleben' in mt and 'Mach mit' in mt, f'[{vname}] Vereinsleben und Mitmachen auf der Startseite')
            pos = await pg.evaluate("[document.querySelector('.mosaic').getBoundingClientRect().top, document.querySelector('#mitmach').getBoundingClientRect().top, document.querySelector('.k112').getBoundingClientRect().top, document.querySelector('#kurz').getBoundingClientRect().top]")
            rec(pos[2] < pos[3] < pos[0] < pos[1], f'[{vname}] Reihenfolge: 112, Termine/Einsätze, Vereinsleben, Mitmachen', str(pos))
            # ---- Rechtliche Prüfungen ----
            if vname == '390':
                ext = []
                pg.on('request', lambda r: ext.append(r.url) if not r.url.startswith(('data:','file:','blob:','about:')) else None)
                for r in ROUTES:
                    await pg.evaluate(f"location.hash='{r}'"); await pg.wait_for_timeout(80)
                rec(not ext, 'Recht/DSGVO: keine Anfragen an Dritte (Schriften, CDNs, Social Media)', ', '.join(ext)[:200])
                import re
                await pg.evaluate("location.hash='einsaetze'"); await pg.wait_for_timeout(80)
                for y in ['2026','2025']:
                    await pg.click(f'button.chip[data-y="{y}"]'); await pg.wait_for_timeout(50)
                    lt = await pg.inner_text('main .list')
                    rec(not re.search(r'stra(ß|ss)e|str\.|weg\b|\d+[a-z]?,', lt, re.I), f'Recht: Einsätze {y} ohne Straßen/Hausnummern (nur Ortsteil)', lt[:120].replace(chr(10),' '))
                    rec(not re.search(r'patient|verletzt|tot\b|leiche|name', lt, re.I), f'Recht: Einsätze {y} ohne Angaben zu Betroffenen')
                await pg.evaluate("location.hash='impressum'"); await pg.wait_for_timeout(80)
                it = await pg.inner_text('main')
                for k in ['§ 5 DDG','VR 1115','§ 18 Abs. 2 MStV','Art. 4 Abs. 1','Vertreten durch','Bildnachweis','Fotos: Feuerwehr Piflas']:
                    rec(k in it, f'Recht/Impressum enthält „{k}“')
                rec('Externe Links' in it, 'Recht/Impressum: Hinweis zu externen Links')
                await pg.evaluate("location.hash='start'"); await pg.wait_for_timeout(100)
                bad = await pg.evaluate("[...document.querySelectorAll('label.chk')].filter(l => [...l.childNodes].some(n => n.nodeType === 3 && n.textContent.trim()) || !l.querySelector(':scope > .ct')).length")
                lh = await pg.evaluate("(() => { const l = document.querySelector('#f-quick label.chk'); const a = l.querySelector('a'); const t = l.querySelector('.ct'); return a.getBoundingClientRect().left >= t.getBoundingClientRect().left - 1 && a.getBoundingClientRect().right <= t.getBoundingClientRect().right + 1; })()")
                rec(bad == 0 and lh, 'Layout: Häkchen-Texte mit Link fließen als ein Absatz')
                await pg.evaluate("location.hash='partner'"); await pg.wait_for_timeout(80)
                vt = await pg.inner_text('main')
                rec(await pg.locator('main h1').inner_text() == 'Partnerfeuerwehren' and 'Ergolding' in vt and 'Oberglaim' in vt, 'Partner: eigene Seite mit Ergolding und Oberglaim')
                rec(await pg.locator('main a[href="https://www.ff-ergolding.de/"]').count() == 1 and await pg.locator('main a[href="https://oberglaim.feuerwehren.bayern/"]').count() == 1, 'Partner: beide Websites verlinkt')
                rec(await pg.locator('#footer a[href="#partner"]').count() == 1, 'Partner: Seite in der Fußzeile verlinkt')
                rec(await pg.locator('#drawer a[href="#partner"]').count() == 1, 'Partner: Seite im Menü')
                gs = await pg.locator('#mnav .mg').all_text_contents()
                rec([g.lower() for g in gs] == ['aktuell','mitmachen','ratgeber','über uns'], 'Menü: in 4 Gruppen gegliedert', str(gs))
                rec(await pg.locator('#mnav a').count() <= 13, 'Menü: kompakt', str(await pg.locator('#mnav a').count()))
                sie = []
                for rt in ['start','jubilaeum','aktuelles','einsaetze','termine','buerger','foerdern','mitmachen','fahrzeuge','jugend','verein','partner','datenschutz','login']:
                    await pg.evaluate(f"location.hash='{rt}'"); await pg.wait_for_timeout(60)
                    t = await pg.inner_text('body')
                    sie += [rt+': '+m for m in re.findall(r'.{20}\b(?:Sie|Ihnen|Ihre?[nmrs]?)\b.{10}', t) if 'Betroffenen. Sie werden' not in m]
                rec(not sie, 'Ansprache: durchgehend „du“', '; '.join(sie)[:200])
                gen = []
                pat = r'\b(Kommandantinnen|Kommandos?|Administration|Kameraden|Feuerwehrmann|Feuerwehrmänner|Besucher|Leser|Ansprechpartner|Unterstützer|Autoren|Administratoren|Freigeber|Jugendleitung)\b|(?<!innen und )\bHelfer\b|\bBürger\b(?! *innen)'
                for rt in ['start','jubilaeum','aktuelles','einsaetze','termine','buerger','foerdern','mitmachen','fahrzeuge','jugend','verein','partner','impressum','datenschutz','login']:
                    await pg.evaluate(f"location.hash='{rt}'"); await pg.wait_for_timeout(60)
                    t = await pg.evaluate("document.body.innerText + ' ' + [...document.querySelectorAll('img[alt]')].map(i => i.alt).join(' ')")
                    gen += [rt+': '+m.group(0) for m in re.finditer(pat, t)]
                rec(not gen, 'Ansprache: N-13 – keine rein männlichen Formen, Ausnahmen Kommandant und Admin', '; '.join(gen)[:200])
                await pg.evaluate("location.hash='mitmachen'"); await pg.wait_for_timeout(60)
                rec('Frauen und Männer sind bei uns gleichermaßen willkommen' in await pg.inner_text('main'), 'Mitmachen: Frauen und Männer ausdrücklich willkommen')
                await pg.evaluate("location.hash='verein'"); await pg.wait_for_timeout(80)
                rec(await pg.locator('main a[href="#partner"]').count() == 1, 'Partner: Verweis von der Verein-Seite')
                ext = await pg.evaluate("[...document.querySelectorAll('#footer a[target=_blank], main a[target=_blank]')].every(a => a.rel.includes('noopener'))")
                rec(ext, 'Partner: externe Links mit rel=noopener')
                await pg.evaluate("location.hash='datenschutz'"); await pg.wait_for_timeout(80)
                dt = await pg.inner_text('main')
                for k in ['Verantwortlicher','Auftragsverarbeitung','Kontakt- und Mitmach-Formular','Einsatzberichte','Fotos','widersprechen','Instagram','Art. 26','Cookie','BayLDA','Art. 15']:
                    rec(k in dt, f'Recht/Datenschutz enthält „{k}“')
                await pg.evaluate("location.hash='jubilaeum'"); await pg.wait_for_timeout(80)
                rec(await pg.locator('#foto-hinweis').count() == 1, 'Recht: Foto-Hinweis für Veranstaltungen (Informationspflicht)')
                await pg.evaluate("location.hash='mitmachen'"); await pg.wait_for_timeout(80)
                rec('unter 16' in await pg.inner_text('main'), 'Recht: Hinweis für Minderjährige im Mitmach-Formular')
                await pg.evaluate("location.hash='foerdern'"); await pg.wait_for_timeout(80)
                ft = await pg.inner_text('main')
                rec('nicht über diese Website' in ft and 'IBAN' not in ft, 'Satzung: keine Spendenannahme über die Website')
            # Unbekannte Route
            await pg.evaluate("location.hash='gibtsnicht'"); await pg.wait_for_timeout(100)
            rec('Für Piflas im Einsatz' in await pg.inner_text('main'), f'[{vname}] unbekannte Adresse zeigt Startseite')
            rec(not errs, f'[{vname}] keine JS-Fehler beim Seitenrundgang', '; '.join(errs)[:300])

            if vname != '390':
                # Fixe Elemente dürfen Footer-Links nicht verdecken (mobile)
                if mobile:
                    await pg.evaluate("location.hash='start'"); await pg.wait_for_timeout(100)
                    await pg.evaluate('window.scrollTo(0, document.body.scrollHeight)'); await pg.wait_for_timeout(100)
                    ov = await pg.evaluate("""() => { const f = document.querySelector('.fab').getBoundingClientRect(); return [...document.querySelectorAll('.foot a')].filter(a => { const r = a.getBoundingClientRect(); return !(r.right < f.left || r.left > f.right || r.bottom < f.top || r.top > f.bottom); }).map(a => a.textContent); }""")
                    rec(not ov, f'[{vname}] Demo-Knopf verdeckt keine Footer-Links', ', '.join(ov))
                await ctx.close(); continue

            # ---------- Abläufe (390) ----------
            async def toast():
                await pg.wait_for_timeout(80); return await pg.inner_text('#toast')
            async def hash(): return await pg.evaluate('location.hash')
            await pg.evaluate("location.hash='start'"); await pg.wait_for_timeout(100)
            # Menü
            await pg.click('.top .menu'); await pg.wait_for_timeout(350)
            tr = await pg.evaluate("getComputedStyle(document.querySelector('#drawer')).transform")
            rec(tr in ('none', 'matrix(1, 0, 0, 1, 0, 0)'), 'Menü öffnet sich', tr)
            await pg.click('#mnav a[href="#einsaetze"]'); await pg.wait_for_timeout(350)
            rec(await hash() == '#einsaetze' and not await pg.evaluate("document.body.classList.contains('mopen')"), 'Menülink navigiert und schließt Menü')
            await pg.click('.top .menu'); await pg.wait_for_timeout(300); await pg.keyboard.press('Escape'); await pg.wait_for_timeout(300)
            rec(not await pg.evaluate("document.body.classList.contains('mopen')"), 'Escape schließt Menü')
            # Einsätze
            await pg.click('button.chip[data-y="2025"]'); await pg.wait_for_timeout(80)
            rec((await pg.inner_text('.stat .num')).strip() == '2', 'Jahresfilter 2025 zeigt 2 Einsätze')
            await pg.click('button.chip[data-y="2026"]'); await pg.click('.list .li >> nth=0'); await pg.wait_for_timeout(80)
            rec('Verkehrsunfall' in await pg.inner_text('h1'), 'Einsatz-Detail öffnet')
            await pg.click('[data-act=detail-close]'); await pg.wait_for_timeout(80)
            rec((await pg.inner_text('h1')).strip() == 'Einsätze', 'Zurück zur Einsatzliste')
            # Termine
            await pg.evaluate("location.hash='termine'"); await pg.wait_for_timeout(80)
            await pg.click('button.chip[data-k="Jugend"]'); await pg.wait_for_timeout(50)
            rec(await pg.locator('main .list .li').count() == 1, 'Terminfilter Jugend')
            await pg.click('button.chip[data-k="Alle"]'); await pg.wait_for_timeout(50)
            # Hero-Knopf öffnet Mitmachen-Seite mit Formular oben
            await pg.evaluate("location.hash='start'"); await pg.wait_for_timeout(100)
            await pg.click('.hero a[href="#mitmachen"]'); await pg.wait_for_timeout(250)
            ftop = await pg.evaluate("document.querySelector('#f-kontakt').getBoundingClientRect().top")
            rec(await hash() == '#mitmachen' and ftop < 400, 'Hero-Knopf „Mitmachen“ öffnet Seite, Formular sofort sichtbar', f'{await hash()} top={ftop}')
            rec(await pg.locator('.hero [data-act]').count() == 0, 'Hero-Knöpfe sind normale Links (ohne Scroll-Skript)')
            # Schnell-Meldung auf der Startseite
            await pg.evaluate("location.hash='start'"); await pg.wait_for_timeout(100)
            await pg.click('#f-quick button[type=submit]')
            rec('Bitte prüfen' in await pg.inner_text('#e-quick'), 'Schnell-Meldung: leere Eingabe abgefangen')
            await pg.fill('#f-quick [name=name]', 'Lisa'); await pg.fill('#f-quick [name=kontakt]', '0171 000000'); await pg.check('#f-quick [name=ds]'); await pg.click('#f-quick button[type=submit]')
            rec('melden uns' in await toast(), 'Schnell-Meldung in 3 Feldern absenden')
            rec('Nächster Übungsabend am 25. Nov' in await pg.inner_text('#mitmach'), 'Nächster Übungsabend wird aus Terminen angezeigt', (await pg.inner_text('#mitmach'))[-120:])
            # Artikel
            await pg.click('.mosaic button >> nth=0'); await pg.wait_for_timeout(150)
            rec(await hash() == '#aktuelles' and 'Befreiung aus dem Pkw' in await pg.inner_text('h1'), 'Foto-Kachel öffnet den Artikel', await hash())
            rec('Jetzt mitmachen' in await pg.inner_text('main'), 'Artikel endet mit Mitmach-Aufruf')
            await pg.click('[data-act=article-close]'); await pg.wait_for_timeout(100)
            rec((await pg.inner_text('h1')).strip() == 'Aktuelles' and await pg.locator('main article').count() == 4, 'Artikelübersicht mit allen Berichten')
            await pg.click('main article >> nth=1 >> [data-act=article]'); await pg.wait_for_timeout(100)
            rec('Dorffest' in await pg.inner_text('h1'), 'Weiterlesen öffnet Dorffest-Artikel')
            # Fördermitglied
            await pg.evaluate("location.hash='foerdern'"); await pg.wait_for_timeout(80)
            txt = await pg.inner_text('main')
            rec('IBAN' not in txt and 'QR' not in txt and 'Spendenkonto' not in txt, 'Keine direkte Spendenannahme (kein Konto, kein QR-Code)')
            rec(await pg.locator('main input').count() == 0, 'Keine Online-Erfassung von Bankdaten')
            await pg.click('[data-doc="Beitrittserklärung"]'); rec('Beitrittserklärung' in await toast(), 'Beitrittserklärung-PDF verlinkt')
            await pg.click('[data-doc="Spendenformular"]'); rec('Spendenformular' in await toast(), 'Spendenformular-PDF verlinkt')
            await pg.evaluate("location.hash='start'"); await pg.wait_for_timeout(80)
            rec(await pg.locator('.hero a[href="#foerdern"]').count() == 1 and await pg.locator('#mitmach a[href="#foerdern"]').count() == 1, 'Fördermitglied: Knopf oben im Bild und Weg im Mitmach-Bereich')
            # Termine: private Termine nicht sichtbar
            st = await pg.inner_text('main')
            rec('Besprechung Führungskräfte' not in st and 'Übung Technische Hilfeleistung' in st, 'Startseite: nicht-private Termine sichtbar, private nicht')
            await pg.evaluate("location.hash='termine'"); await pg.wait_for_timeout(80)
            rec('Besprechung Führungskräfte' not in await pg.inner_text('main'), 'Terminseite zeigt keine privaten Termine')
            # Mitmachen
            await pg.evaluate("location.hash='mitmachen'"); await pg.wait_for_timeout(80)
            await pg.fill('#f-kontakt [name=kontakt]', 'x'); await pg.click('#f-kontakt button[type=submit]')
            rec('Dein Name' in await pg.inner_text('#e-kontakt'), 'Kontaktformular: fehlender Name erkannt', await pg.inner_text('#e-kontakt'))
            await pg.fill('#f-kontakt [name=name]', 'Tom'); await pg.check('#f-kontakt [name=ds]'); await pg.click('#f-kontakt button[type=submit]')
            rec('Danke' in await toast(), 'Kontaktformular absenden')
            # Login-Schutz
            await pg.evaluate("location.hash='mitglieder'"); await pg.wait_for_timeout(120)
            rec(await hash() == '#login', 'Backend ohne Login leitet zum Login')
            await pg.click('#f-login button[type=submit]')
            rec('E-Mail' in await pg.inner_text('#e-login'), 'Login: leere Felder abgefangen')
            await pg.fill('#f-login [name=mail]', 'max@beispiel.de'); await pg.fill('#f-login [name=pw]', 'geheim'); await pg.select_option('#f-login [name=role]', 'Administrator'); await pg.click('#f-login button[type=submit]'); await pg.wait_for_timeout(80)
            rec(await pg.locator('#f-2fa').count() == 1, 'Login führt zur 2-Faktor-Abfrage')
            await pg.fill('#f-2fa input', '12'); await pg.click('#f-2fa button[type=submit]')
            rec('Code' in await pg.inner_text('#e-2fa'), '2FA: falscher Code abgelehnt')
            await pg.fill('#f-2fa input', '123456'); await pg.click('#f-2fa button[type=submit]'); await pg.wait_for_timeout(150)
            rec(await hash() == '#mitglieder', 'Nach Login zurück zur gewünschten Seite (Mitglieder)', await hash())
            # Mitglieder
            n0 = await pg.locator('#mlist .card').count()
            await pg.fill('#f-invite [name=n]', 'Neu Mitglied'); await pg.fill('#f-invite [name=m]', 'kaputt'); await pg.click('#f-invite button[type=submit]')
            rec('E-Mail' in await pg.inner_text('#e-invite'), 'Einladung: ungültige E-Mail abgefangen')
            await pg.fill('#f-invite [name=m]', 'neu@beispiel.de'); await pg.select_option('#f-invite [name=r]', 'Freigeber'); await pg.click('#f-invite button[type=submit]'); await pg.wait_for_timeout(80)
            rec(await pg.locator('#mlist .card').count() == n0 + 1 and 'neu@beispiel.de' not in await pg.inner_text('#mlist') and 'Neu Mitglied' in await pg.inner_text('#mlist'), 'Einladung erscheint in der Liste mit Rolle')
            await pg.click('[data-act=resend] >> nth=0'); rec('erneut' in await toast(), 'Einladung erneut senden')
            n1 = await pg.locator('#mlist .card').count(); await pg.click('[data-act=revoke] >> nth=0'); await pg.wait_for_timeout(80)
            rec(await pg.locator('#mlist .card').count() == n1 - 1, 'Einladung zurückziehen')
